class stringx {};
extern stringx ksGlobalTextArray[];

class FEMenuEntry {};

class BoxText {
public:
    void changeText(const stringx &) __asm__("changeText__7BoxTextRC7stringx");
    void makeBox(float, float) __asm__("makeBox__7BoxTextff");
    void changePos(float, float) __asm__("changePos__7BoxTextff");
};

class HelpBar {
public:
    void DisableHelpbar() __asm__("DisableHelpbar__7HelpBar");
};

class FEManager {
public:
    HelpBar *helpbar;
};
extern FEManager frontendmanager;

class SoundScriptManager {
public:
    static SoundScriptManager *instance __asm__("_18SoundScriptManager$instance");
    static SoundScriptManager *inst() { return instance; }
    void pause() __asm__("pause__18SoundScriptManager");
    void unpause() __asm__("unpause__18SoundScriptManager");
    int playEvent(int, void * = 0, float = 0) __asm__("playEvent__18SoundScriptManager9EventTypeP6entityf");
};

enum { SS_FE_ONX = 24, GT_FE_MENU_LOADING = 0 };

class BeachFrontEnd {
public:
    FEMenuEntry *highlighted;
    FEMenuEntry *secondary_cursor;
    FEMenuEntry *fe_return;
    FEMenuEntry *yes_entry;
    BoxText *return_question;
    int map_wait_loading;
    bool in_frontend;

    void FromFEReturn() __asm__("FromFEReturn__13BeachFrontEnd");
    void Pick() __asm__("Pick__13BeachFrontEnd");
    void Select(int) __asm__("Select__13BeachFrontEndi");
};

void BeachFrontEnd::Select(int entry_index)
{
    if (!in_frontend)
        SoundScriptManager::inst()->unpause();

    if(!in_frontend && highlighted == fe_return)
    {
        SoundScriptManager::inst()->playEvent(SS_FE_ONX);
        if(secondary_cursor == yes_entry)
        {
            map_wait_loading = 3;
            return_question->changeText(ksGlobalTextArray[GT_FE_MENU_LOADING]);
            return_question->makeBox(200, 100);
            return_question->changePos(320, 240);
            frontendmanager.helpbar->DisableHelpbar();
        }
        else FromFEReturn();
    }
    else Pick();
    if (!in_frontend)
        SoundScriptManager::inst()->pause();
}
